# Let's manually analyze each changed pair systematically
inputs = ['bizkiz', 'kvj', 'uvjzeg', 'hhcwu', 'vghhac']
outputs = ['biijkiij', 'kvva', 'uvvaigg', 'hhcwu', 'vghhebc']

# Create a function to compare two strings and find minimal edits
def find_minimal_edit(s_in, s_out):
    # Find first difference
    min_len = min(len(s_in), len(s_out))

    # Look for longest substring that matches
    for length in range(min_len, 0, -1):
        for i in range(len(s_in) - length + 1):
            substr = s_in[i:i+length]
            if substr in s_out:
                # Find where it appears in output
                j = s_out.find(substr)
                # Check if the rest matches
                if (i + length <= len(s_in) and 
                    j + length <= len(s_out) and
                    s_in[i+length:] == s_out[j+length:]):
                    return (substr, s_out[j:j+length], i)

    # If no substring match, try character by character
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # For now, assume single character replacement
            return (s_in[i], s_out[i], i)

    return None

# Analyze each changed pair
changed_pairs = []
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        changed_pairs.append((i, inputs[i], outputs[i]))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

print("\nAnalyzing each transformation:")
for idx, inp, outp in changed_pairs:
    print(f"\nPair {idx}: '{inp}' -> '{outp}'")
    # Simple character-by-character analysis for now
    for i in range(min(len(inp), len(outp))):
        if inp[i] != outp[i]:
            print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")

    # Check for longer patterns
    if len(inp) == len(outp):
        # Same length - look for replacements
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Replacement: '{inp[i]}' -> '{outp[i]}'")

